package io.invenlio.procurement;import io.swagger.v3.oas.annotations.Operation;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1")@SecurityRequirement(name="bearerAuth")class ProcurementChildController{private final ProcurementChildQueryService service;ProcurementChildController(ProcurementChildQueryService s){service=s;}@Operation(summary="List a supplier's addresses")@GetMapping("/suppliers/{supplierId}/addresses")List<ProcurementService.Address>addresses(@PathVariable UUID supplierId,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return service.addresses(supplierId,page,size);}@GetMapping("/supplier-addresses/{id}")ProcurementService.Address address(@PathVariable UUID id){return service.address(id);}@Operation(summary="List a supplier's contacts")@GetMapping("/suppliers/{supplierId}/contacts")List<ProcurementService.Contact>contacts(@PathVariable UUID supplierId,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return service.contacts(supplierId,page,size);}@GetMapping("/supplier-contacts/{id}")ProcurementService.Contact contact(@PathVariable UUID id){return service.contact(id);}}
